// Far from (0,0), both signs, and disconnected molecules must remain anchored.
{
    auto reset=[&](){s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.refresh();};
    auto center=[&](const std::vector<ObjectId>& ids){auto p=s.doc.atoms().get(ids.front())->position;Box bounds(p,p);for(auto id:ids)bounds.add(s.doc.atoms().get(id)->position);return (bounds.min+bounds.max)*.5;};
    reset();std::vector<ObjectId> left,right;ObjectId atom,bond;
    for(auto offset:{Vec2(-450,-320),Vec2(460,340)}){std::vector<ObjectId> ids;for(auto point:{Vec2(0,0),Vec2(25,2),Vec2(31,43)}){s.doc.addAtom(offset+point,6,&atom);ids.push_back(atom);}s.doc.addBond(ids[0],ids[1],&bond);s.doc.addBond(ids[1],ids[2],&bond);if(left.empty())left=ids;else right=ids;}
    ObjectId caption;s.doc.addText(Vec2(430,420),10,"keep caption",&caption);s.refresh();auto oldLeft=center(left),oldRight=center(right),oldCaption=s.doc.texts().get(caption)->position;auto before=s.doc.digest();auto oldView=s.view();s.selected=s.all();chemistryAction("clean");require(s.doc.digest()!=before,"actual native cleanup adjusts distorted structures");require(length(center(left)-oldLeft)<1e-6&&length(center(right)-oldRight)<1e-6,"native cleanup preserves each disconnected component's original bounding center");require(s.doc.texts().get(caption)->position==oldCaption,"ordinary cleanup leaves nearby text in place");require(s.view().center==oldView.center&&s.view().scale==oldView.scale,"cleanup preserves viewport");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before,"anchored cleanup is one undo");require(s.undo(true).ok()&&s.doc.digest()==after,"anchored cleanup redo");
    // Partial atom selection expands to its whole component, preserving the rest.
    auto rightBefore=center(right);s.selected={ObjectRef(ObjectKind::Atom,left[1])};oldLeft=center(left);chemistryAction("clean");require(length(center(left)-oldLeft)<1e-6&&center(right)==rightBefore,"partial selection preserves the selected molecule's location and does not move other molecules");
    std::ofstream(testOut+"/cleanup_position_tests.json")<<"{\"native_service\":true,\"positive_and_negative_coordinates\":true,\"separate_component_centers\":true,\"partial_selection\":true,\"caption_unchanged\":true,\"viewport_unchanged\":true,\"undo_redo\":true}";reset();
}
